/**
 * SMART discovery: finding the FHIR base — the SMART `iss` — a server URL
 * signs in through, and the OAuth endpoints it advertises.
 *
 * A server URL is a FHIR base: a Wildflower server serves FHIR at its root, so
 * its address is its FHIR base, and a plain SMART server's is the URL itself
 * (the SmartHealthIT demo's `…/fhir`). {@link discoverSmartEndpoints} reads the
 * configuration under it, and the document says which kind of server it is: a
 * Wildflower server lists {@link WILDFLOWER_SERVER_CAPABILITY} among its
 * `capabilities`. A Wildflower server answers from
 * `apps/host/wildflower-server/fhir-r4-rust/src/smart_configuration.rs`
 * (exempt from the bearer gate — `authorization-server-rust`'s
 * `require_valid_bearer_token`), advertising `authorization_endpoint` and
 * `token_endpoint` derived from the origin it was served on. Those advertised
 * URLs are what the client uses; it never assumes `/oauth/authorize` sits at
 * the target's root.
 *
 * The validation is pure and returns an `Either`; the fetch is the async edge
 * and returns an `Effect` failing with {@link DiscoveryFailed}. Every failure a
 * reader can actually hit — target that is not a Wildflower server, server
 * down, blocked by CORS or mixed content — arrives as that one tagged error,
 * whose `reason` the header bar renders verbatim.
 */

import { Data, Effect, Either, Option, Schema } from 'effect'

/** Raised when the chosen target cannot be signed in to, with the reason why. */
class DiscoveryFailed extends Data.TaggedError('DiscoveryFailed')<{
  readonly reason: string
}> {}

/** The discovery document's path, relative to the SMART `iss` (a FHIR base). */
const SMART_CONFIGURATION_PATH = '/.well-known/smart-configuration'

/** The discovery URL for the FHIR base `fhirBaseUrl` (already canonical: no trailing slash). */
const smartConfigurationUrl = (fhirBaseUrl: string): string =>
  `${fhirBaseUrl}${SMART_CONFIGURATION_PATH}`

/** The two endpoints the authorization-code flow needs. */
interface SmartEndpoints {
  readonly authorizationEndpoint: string
  readonly tokenEndpoint: string
}

/**
 * The SMART capability a Wildflower server's configuration lists, and a plain
 * SMART server's doesn't. `smart-discovery.test.ts` reads the document
 * `fhir-r4-rust` serves (its committed `snapshots/smart-configuration.json`)
 * and expects a Wildflower server of it, so the two can't drift apart.
 */
const WILDFLOWER_SERVER_CAPABILITY = 'wildflower-server'

/**
 * A Wildflower server, found by its SMART configuration listing
 * {@link WILDFLOWER_SERVER_CAPABILITY}. Its FHIR base is its address.
 */
const WildflowerServer = Schema.TaggedStruct('WildflowerServer', {
  fhirBaseUrl: Schema.NonEmptyString,
})

/**
 * A plain SMART server, whose SMART configuration doesn't list
 * {@link WILDFLOWER_SERVER_CAPABILITY}. Its FHIR base is the server URL itself
 * (the SmartHealthIT demo's `…/fhir`).
 */
const PlainSmartServer = Schema.TaggedStruct('PlainSmartServer', {
  fhirBaseUrl: Schema.NonEmptyString,
})

/**
 * Which kind of server discovery found at a server URL, and the FHIR base that
 * served its configuration — the `iss`, and the `aud` a sign-in names. A Schema
 * because it rides the pending record across the redirect and comes back on the
 * `Session`.
 */
const SmartServer = Schema.Union(WildflowerServer, PlainSmartServer)
type SmartServer = Schema.Schema.Type<typeof SmartServer>

/**
 * A server's SMART issuer as discovery found it: the {@link SmartServer} that
 * served the configuration and the endpoints it advertised.
 *
 * `managementEndpoint` is SMART's page where the reader manages what they have
 * authorized (a Wildflower server's is the Wildflower Authorization app), and
 * `wildflowerAuthorizationApi` is the base of a Wildflower server's
 * authorization JSON API, which a plain SMART server doesn't advertise. Each is
 * `None` when the document omits it or doesn't name a usable URL.
 */
interface SmartIssuer {
  readonly smartServer: SmartServer
  readonly endpoints: SmartEndpoints
  readonly managementEndpoint: Option.Option<string>
  readonly wildflowerAuthorizationApi: Option.Option<string>
}

/**
 * Hosts a browser treats as potentially trustworthy over plain `http:`
 * (W3C Secure Contexts §3.1): the loopback addresses. A desktop Wildflower host
 * serves its API on one of these, so an `http:` endpoint pointing at loopback is
 * accepted even from the HTTPS-published page — the same exception that makes
 * the client's ordinary requests to a loopback server work at all.
 */
const isLoopbackHost = (hostname: string): boolean =>
  hostname === 'localhost' ||
  hostname === '[::1]' ||
  hostname === '::1' ||
  /^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(hostname)

/**
 * Why a URL is not one the client will send a reader (or a token request) to,
 * as a sentence about that URL.
 */
class UnusableEndpointUrl extends Data.TaggedError('UnusableEndpointUrl')<{
  readonly reason: string
}> {}

/**
 * `candidate` as an endpoint URL the client will send a reader (or a token
 * request) to, or why it is not one.
 *
 * Rejected: anything that is not an absolute `http:`/`https:` URL; embedded
 * credentials (userinfo, which a redirect would carry into the address bar); a
 * fragment (the authorize URL grows query parameters, and a fragment would
 * strand them); and plain `http:` to a non-loopback host while the client
 * itself is on a secure page — a downgrade the browser would block anyway, and
 * which would put an access token on the wire in the clear.
 */
const endpointUrlFrom = (
  candidate: string,
  options: { readonly pageIsSecure: boolean }
): Either.Either<string, UnusableEndpointUrl> => {
  let url: URL
  try {
    url = new URL(candidate.trim())
  } catch {
    return Either.left(new UnusableEndpointUrl({ reason: 'It is not an absolute URL.' }))
  }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') {
    return Either.left(
      new UnusableEndpointUrl({
        reason: `It is a ${url.protocol} URL, not an http or https one.`,
      })
    )
  }
  if (url.username !== '' || url.password !== '') {
    return Either.left(new UnusableEndpointUrl({ reason: 'It carries a user name or password.' }))
  }
  if (url.hash !== '') {
    return Either.left(
      new UnusableEndpointUrl({
        reason: 'It carries a fragment (#…), which would strand the parameters sign-in adds.',
      })
    )
  }
  if (options.pageIsSecure && url.protocol === 'http:' && !isLoopbackHost(url.hostname)) {
    return Either.left(
      new UnusableEndpointUrl({
        reason: 'It is plain http to a host off this computer, and this page is served over https.',
      })
    )
  }
  return Either.right(url.toString())
}

/**
 * `candidate` as an endpoint URL the client will send a reader (or a token
 * request) to, or `undefined` when it is not one — {@link endpointUrlFrom}
 * without the reason.
 */
const usableEndpointUrl = (
  candidate: string,
  options: { readonly pageIsSecure: boolean }
): string | undefined => Either.getOrUndefined(endpointUrlFrom(candidate, options))

/**
 * Why a page cannot reach `serverUrl`, or `undefined` when it can.
 *
 * States when the target is chosen what {@link usableEndpointUrl} enforces
 * after the fetch, so the reader gets the real reason rather than a discovery
 * failure that reads as "the server is down". Loopback is deliberately not a
 * failure, for the reason {@link isLoopbackHost} gives.
 */
const insecureTargetReason = (
  serverUrl: string,
  options: { readonly pageIsSecure: boolean }
): string | undefined => {
  if (!options.pageIsSecure) return undefined
  let url: URL
  try {
    url = new URL(serverUrl)
  } catch {
    return undefined
  }
  if (url.protocol !== 'http:' || isLoopbackHost(url.hostname)) return undefined
  return (
    `This page is served over https, so the browser will block its requests to ` +
    `${serverUrl}. Use an https address for the server, open this page over ` +
    `http from the server itself, or use a server on this computer.`
  )
}

/**
 * The part of a SMART configuration document (SMART App Launch §2.1) this
 * client reads. Only the two endpoints the flow needs are required.
 * `wildflower_authorization_api` is a Wildflower extension field.
 */
const SmartConfiguration = Schema.Struct({
  authorization_endpoint: Schema.String,
  token_endpoint: Schema.String,
  management_endpoint: Schema.optionalWith(Schema.String, { as: 'Option', exact: true }),
  wildflower_authorization_api: Schema.optionalWith(Schema.String, { as: 'Option', exact: true }),
  code_challenge_methods_supported: Schema.optional(Schema.Array(Schema.String)),
  capabilities: Schema.optional(Schema.Array(Schema.String)),
})

const decodeSmartConfiguration = Schema.decodeUnknownEither(SmartConfiguration)

/**
 * The issuer the configuration `document` served under the FHIR base
 * `fhirBaseUrl` describes — which kind of server it is and the endpoints it
 * advertises — or the reason it is unusable.
 *
 * `code_challenge_methods_supported` is checked for `S256` when present,
 * because a server that cannot do S256 cannot complete this client's flow (the
 * authorization server authorize endpoint mandates it) and failing here says so plainly;
 * a document that omits the field is given the benefit of the doubt rather than
 * blocked on a hint.
 */
const smartIssuerFrom = (
  fhirBaseUrl: string,
  document: unknown,
  options: { readonly pageIsSecure: boolean }
): Either.Either<SmartIssuer, DiscoveryFailed> => {
  const decoded = decodeSmartConfiguration(document)
  if (Either.isLeft(decoded)) {
    return Either.left(
      new DiscoveryFailed({
        reason:
          'The server’s SMART configuration is not a document that names an ' +
          'authorization_endpoint and token_endpoint.',
      })
    )
  }
  const configuration = decoded.right
  const authorizationEndpoint = usableEndpointUrl(configuration.authorization_endpoint, options)
  const tokenEndpoint = usableEndpointUrl(configuration.token_endpoint, options)
  if (authorizationEndpoint === undefined || tokenEndpoint === undefined) {
    return Either.left(
      new DiscoveryFailed({
        reason:
          'The server’s SMART configuration does not advertise a usable ' +
          'authorization_endpoint and token_endpoint over https (or loopback).',
      })
    )
  }
  const methods = configuration.code_challenge_methods_supported
  if (methods !== undefined && !methods.includes('S256')) {
    return Either.left(
      new DiscoveryFailed({
        reason: 'The server does not support PKCE with S256, which sign-in needs.',
      })
    )
  }
  const smartServer = (configuration.capabilities ?? []).includes(WILDFLOWER_SERVER_CAPABILITY)
    ? WildflowerServer.make({ fhirBaseUrl })
    : PlainSmartServer.make({ fhirBaseUrl })
  const usableOptionalUrl = (candidate: Option.Option<string>): Option.Option<string> =>
    candidate.pipe(Option.flatMapNullable((url) => usableEndpointUrl(url, options)))
  return Either.right({
    smartServer,
    endpoints: { authorizationEndpoint, tokenEndpoint },
    managementEndpoint: usableOptionalUrl(configuration.management_endpoint),
    wildflowerAuthorizationApi: usableOptionalUrl(configuration.wildflower_authorization_api),
  })
}

/**
 * Find the SMART issuer at `serverUrl` (canonical: no trailing slash), a FHIR
 * base, and validate what it advertises. The {@link SmartServer} it describes
 * is returned with the endpoints: its FHIR base is the `aud` the sign-in names,
 * and its kind is what the signed-in app may offer.
 *
 * Every way the request can fail — unreachable, an error status (a 404
 * included: there is no configuration there), a non-JSON body — is a
 * {@link DiscoveryFailed} naming the URL.
 */
const discoverSmartEndpoints = (
  serverUrl: string,
  options: { readonly fetch: typeof globalThis.fetch; readonly pageIsSecure: boolean }
): Effect.Effect<SmartIssuer, DiscoveryFailed> =>
  Effect.gen(function* () {
    const url = smartConfigurationUrl(serverUrl)
    const response = yield* Effect.tryPromise({
      try: () => options.fetch(url, { headers: { Accept: 'application/json' } }),
      // A network-level failure is indistinguishable from a CORS rejection to
      // the page, so name both possibilities instead of guessing.
      catch: () =>
        new DiscoveryFailed({
          reason: `Could not reach ${url}. The server may be down, or the browser may have blocked the request.`,
        }),
    })
    if (response.status === 404) {
      return yield* new DiscoveryFailed({
        reason:
          `${url} was not found (404). ` +
          'Enter a Wildflower server’s address, or a SMART on FHIR server’s FHIR base URL.',
      })
    }
    if (!response.ok) {
      return yield* new DiscoveryFailed({
        reason: `${url} answered ${String(response.status)}. Is this a Wildflower server?`,
      })
    }
    const document = yield* Effect.tryPromise({
      try: (): Promise<unknown> => response.json(),
      catch: () =>
        new DiscoveryFailed({
          reason: `${url} did not answer with JSON. Is this a Wildflower server?`,
        }),
    })
    return yield* smartIssuerFrom(serverUrl, document, { pageIsSecure: options.pageIsSecure })
  })

export {
  DiscoveryFailed,
  PlainSmartServer,
  SmartServer,
  WildflowerServer,
  SMART_CONFIGURATION_PATH,
  smartConfigurationUrl,
  isLoopbackHost,
  endpointUrlFrom,
  UnusableEndpointUrl,
  usableEndpointUrl,
  insecureTargetReason,
  smartIssuerFrom,
  discoverSmartEndpoints,
  WILDFLOWER_SERVER_CAPABILITY,
}
export type { SmartEndpoints, SmartIssuer }
